export const getToAccounts = createSelector(
  [
    (state: BridgeAppState) => getToChain(state)?.chainId,
    getWalletsWithAccounts,
    (state: BridgeAppState) => state,
  ],
  (toChainId, accountsByWallet, state) => {
    if (!toChainId) {
      return [];
    }
    const internalAccounts = getInternalAccountsByScope(state, toChainId);

    return internalAccounts.map((account) => ({
      ...account,
      isExternal: false,
      walletName:
        account.options.entropy?.type === 'mnemonic'
          ? accountsByWallet[`entropy:${account.options.entropy.id}`]?.metadata
              .name
          : accountsByWallet[`keyring:${account.metadata.keyring.type}`]
              ?.metadata.name,
      displayName:
        getAccountGroupNameByInternalAccount(state, account) ??
        account.metadata.name ??
        account.address,
    }));
  },
);

export const getFromNativeBalance = createSelector(
  [
    getFromChain,
    (state: BridgeAppState) => state.bridge.fromNativeBalance,
    getMultichainBalances,
    (state: BridgeAppState) => getFromAccount(state)?.id,
  ],
  (fromChain, fromNativeBalance, nonEvmBalancesByAccountId, id) => {
    if (!fromChain || !id) {
      return null;
    }

    const { chainId } = fromChain;
    const { decimals, assetId } = getNativeAssetForChainId(chainId);

    // Use the balance provided by the multichain balances controller for non-EVM chains
    if (isNonEvmChain(chainId)) {
      return nonEvmBalancesByAccountId?.[id]?.[assetId]?.amount ?? null;
    }

    return calcNormalizedTokenAmount(fromNativeBalance, decimals) ?? null;
  },
);

export const getFromTokenBalance = createSelector(
  [
    getFromToken,
    getFromChain,
    (state: BridgeAppState) => state.bridge.fromTokenBalance,
    getMultichainBalances,
    getFromAccount,
  ],
  (
    fromToken,
    fromChain,
    fromTokenBalance,
    nonEvmBalancesByAccountId,
    fromAccount,
  ) => {
    if (!fromToken || !fromChain || !fromAccount) {
      return null;
    }
    const { id } = fromAccount;
    const { chainId, decimals, assetId } = fromToken;

    // Use the balance provided by the multichain balances controller for non-EVM chains
    if (isNonEvmChain(chainId)) {
      return (
        nonEvmBalancesByAccountId?.[id]?.[assetId]?.amount ??
        fromToken.balance ??
        null
      );
    }

    return calcNormalizedTokenAmount(fromTokenBalance, decimals) ?? null;
  },
);

// Returns normalized balances for the src network, appends balances from bridge state
export const getFromBalances = createSelector(
  [
    getFromNativeBalance,
    getFromTokenBalance,
    getFromToken,
    (state: BridgeAppState) =>
      state.metamask.assetsBalance?.[getFromAccount(state)?.id ?? ''],
  ],
  (fromNativeBalance, fromTokenBalance, fromToken, maybeNormalizedBalances) => {
    const normalizedBalances = maybeNormalizedBalances ?? {};
    const nativeAsset = getNativeAssetForChainId(fromToken.chainId);

    const balanceAssetIds = Object.keys(normalizedBalances) as CaipAssetType[];

    const nativeBalanceAssetIdToUse =
      balanceAssetIds.find((assetId) =>
        assetIdsMatch(assetId, nativeAsset.assetId),
      ) ?? nativeAsset.assetId;

    const fromTokenBalanceAssetIdToUse =
      balanceAssetIds.find((assetId) =>
        assetIdsMatch(assetId, fromToken.assetId),
      ) ?? fromToken.assetId;

    return {
      ...Object.fromEntries(
        Object.entries(normalizedBalances).map(([assetId, balance]) => [
          assetId,
          balance.amount,
        ]),
      ),
      [fromTokenBalanceAssetIdToUse]:
        fromTokenBalance ??
        normalizedBalances[fromTokenBalanceAssetIdToUse]?.amount ??
        '0',
      [nativeBalanceAssetIdToUse]:
        fromNativeBalance ??
        normalizedBalances[nativeBalanceAssetIdToUse]?.amount ??
        '0',
    };
  },
);

