import type { BridgeToken } from '../../../ducks/bridge/types';

export const formatTokenAmount = (
  locale: string,
  amount: string | undefined | null = '',
  symbol: string = '',
  roundingMode?: number,
) => {
  if (!amount) {
    return '0';
  }
  const stringifiedAmount = formatAmount(
    locale,
    new BigNumber(amount),
    roundingMode,
  );

  return [stringifiedAmount, symbol].join(' ').trim();
};

export const formatCurrencyAmount = (
  stringifiedDecAmount: string | null | undefined,
  currency: string,
  precision: number = DEFAULT_PRECISION,
) => {
  if (!stringifiedDecAmount) {
    return undefined;
  }
  const amount = new BigNumber(stringifiedDecAmount);

  if (precision === 0) {
    if (amount.lt(0.01)) {
      return '<$0.01';
    }
    if (amount.lt(1)) {
      return formatCurrency(amount.toString(), currency, 2);
    }
  }
  return formatCurrency(amount.toString(), currency, precision);
};

export const convertTokenAmountToFiat = (
  tokenAmount: string | null | undefined,
  conversionRate: number | null | undefined,
) => {
  if (!tokenAmount || !conversionRate) {
    return;
  }
  if (!Number.isFinite(conversionRate) || conversionRate <= 0) {
    return;
  }

  try {
    const amount = new BigNumber(tokenAmount).times(conversionRate.toString());
    return new BigNumber(amount.toFixed(2)).toString();
  } catch {
    return undefined;
  }
};

export const convertFiatToTokenAmount = (
  fiatAmount: string | null | undefined,
  conversionRate: number | null | undefined,
  tokenDecimals: number | undefined,
) => {
  if (!fiatAmount || !conversionRate || tokenDecimals === undefined) {
    return;
  }
  if (!Number.isFinite(conversionRate) || conversionRate <= 0) {
    return;
  }

  try {
    const amount = new BigNumber(fiatAmount).div(conversionRate.toString());
    return new BigNumber(
      amount.toFixed(tokenDecimals, BigNumber.ROUND_DOWN),
    ).toString();
  } catch {
    return undefined;
  }
};

/**
 * Formats network fees with dynamic precision to avoid showing $0.00 for non-zero fees.
 * If fees are less than $0.01, increases decimal places up to 4 until the first non-zero digit is shown.
 * If fees are non-zero but smaller than $0.0001, rounds up to $0.0001.
 *
 * @param stringifiedDecAmount - The fee amount as a string
 * @param currency - The currency code (e.g., 'USD')
 * @returns Formatted currency string with appropriate precision
 */
export function formatNetworkFee(
  stringifiedDecAmount: string | null | undefined,
  currency: string,
): string | undefined {
  if (!stringifiedDecAmount) {
    return undefined;
  }

  const amount = new BigNumber(stringifiedDecAmount);

  // If amount is zero, return formatted zero
  if (amount.isZero()) {
    return formatCurrency(amount.toString(), currency, 2);
  }

  // If amount is >= $0.01, use standard 2 decimal places
  if (amount.gte(0.01)) {
    return formatCurrency(amount.toString(), currency, 2);
  }

  // For amounts < $0.01, find the precision that shows the first non-zero digit
  // Try precision from 2 to 4 (max allowed)
  for (let precision = 2; precision <= 4; precision++) {
    // Scale the amount by 10^precision to move the target digit to the ones place
    // Example: 0.0005 with precision 3 → 0.5 (moves 3rd decimal to ones place)
    const scaleFactor = new BigNumber(10).pow(precision);
    const scaledAmount = amount.times(scaleFactor);

    // Round using ROUND_HALF_UP to match currency formatter's rounding behavior
    // If the rounded value is non-zero, this precision will show a non-zero digit
    const roundedValue = scaledAmount.round(0, BigNumber.ROUND_HALF_UP);

    if (roundedValue.gt(0)) {
      return formatCurrency(amount.toString(), currency, precision);
    }
  }

  // If after 4 decimal places it's still showing as zero but original amount > 0,
  // round up to $0.0001
  if (amount.gt(0)) {
    return formatCurrency('0.0001', currency, 4);
  }

  // Fallback to 2 decimal places
  return formatCurrency(amount.toString(), currency, 2);
}

export const sanitizeAmountInput = (
  textToSanitize: string,
  dropNumbersAfterSecondDecimal = true,
) => {
  // Remove non-numeric and non-decimal characters
  const cleanedString = textToSanitize.replace(/[^\d.]+/gu, '');
  // Find first decimal point and use its index to split the string into two parts
  const pointIndex = cleanedString.indexOf('.');
  const firstPart = cleanedString.slice(0, pointIndex + 1);
  const secondPart = dropNumbersAfterSecondDecimal
    ? // Ignore digits after second decimal point
      cleanedString.slice(pointIndex + 1).split('.')[0]
    : // Preserve digits after second decimal point
      cleanedString.slice(pointIndex + 1).replace(/[^\d]+/gu, '');

  return [firstPart, secondPart].filter(Boolean).join('');
};

/**
 * Sanitizes the amount string for BigNumber calculations by converting empty strings or single decimal points to '0'.
 *
 * @param amount - The raw amount string from input
 * @returns A safe string for BigNumber operations
 */
export const safeAmountForCalc = (
  amount: string | null | undefined,
): string => {
  if (!amount) {
    return '0';
  }
  const sanitized = sanitizeAmountInput(amount);
  return sanitized === '' || sanitized === '.' ? '0' : sanitized;
};

export const isQuoteExpiredOrInvalid = ({
  activeQuote,
  toToken,
  isQuoteExpired,
}: {
  activeQuote: QuoteResponse | null;
  toToken: BridgeToken | null;
  isQuoteExpired: boolean;
}): boolean => {
  // 1. Ignore quotes that are expired
  if (isQuoteExpired) {
    return true;
  }

  // 2. Ensure the quote still matches the currently selected destination asset / chain
  if (activeQuote && toToken) {
    return !assetIdsMatch(
      activeQuote.quote.dest.asset.assetId,
      toToken.assetId,
    );
  }

  return false;
};

/**
 * Converts basis points (BPS) to percentage
 * 1 BPS = 0.01%
 *
 * @param bps - The value in basis points (e.g., "87.5" or 87.5)
 * @returns The percentage value as a string (e.g., "0.875")
 */
export const bpsToPercentage = (
  bps: string | number | undefined,
): string | undefined => {
  if (bps === undefined || bps === null) {
    return undefined;
  }

  const bpsValue = typeof bps === 'string' ? parseFloat(bps) : bps;

  if (isNaN(bpsValue)) {
    return undefined;
  }

  // BPS to percentage: divide by 100
  return (bpsValue / 100).toString();
};

export const readMmFee = (quote: QuoteResponse) => {
  // Get the fee percentage from the quote or fallback to default
  const quoteBpsFee = quote.quote.feeData?.metabridge?.[0]?.quoteBpsFee;
  const baseBpsFee = quote.quote.feeData?.metabridge?.[0]?.baseBpsFee;
  const discountType = quote.quote.feeData?.metabridge?.[0]?.discountType;
  const quoteFeePercentage = bpsToPercentage(quoteBpsFee);
  const baseFeePercentage = bpsToPercentage(baseBpsFee);

  const isDiscounted = Boolean(
    discountType &&
    quoteFeePercentage &&
    baseFeePercentage &&
    Number(baseBpsFee) > Number(quoteBpsFee),
  );

  return {
    isDiscounted,
    baseFeePercentage,
    quoteFeePercentage,
    discountType,
  };
};
export const getGasFees = (quote?: QuoteResponse) => {
  return sumAmounts(quote?.quote.feeData[FeeType.NETWORK]);
};

export const getTotalNetworkFee = (quote?: QuoteResponse | null) => {
  return sumAmounts(
    quote?.quote.feeData[FeeType.NETWORK],
    quote?.quote.feeData[FeeType.RELAYER],
  );
};

export const getNativeReserve = (quote?: QuoteResponse | null) => {
  return sumAmounts(quote?.quote.feeData.reserve);
};

export const getIncludedTxFees = (quote?: QuoteResponse | null) => {
  return sumAmounts(quote?.quote.feeData[FeeType.TX_FEE]);
};

export const getDestChainId = (quote: QuoteResponse) => {
  const destAssetId = quote.quote.dest.asset.assetId;
  return parseCaipAssetType(destAssetId).chainId;
};

export const getPriceImpactNumber = (quote?: QuoteResponse | null) => {
  const priceImpactNumber = Number(quote?.quote.priceData?.priceImpact?.amount);
  if (Number.isNaN(priceImpactNumber)) {
    return null;
  }
  return priceImpactNumber;
};
